set-variable.value:
@{
            var reserved = new [] { "scope", "scopes", "scopeName", "scopeNames", "failOnMissingScope" };
            foreach (var key in context.Request.Url.Query.Keys)
            {
                if (reserved.Any(name => string.Equals(name, key, System.StringComparison.OrdinalIgnoreCase))) return true;
            }
            if (context.Request.Body == null) return false;
            try
            {
                var body = context.Request.Body.As<JToken>(preserveContent: true);
                var container = body as JContainer;
                if (container == null) return false;
                foreach (var property in container.Descendants().OfType<JProperty>())
                {
                    if (reserved.Any(name => string.Equals(name, property.Name, System.StringComparison.OrdinalIgnoreCase))) return true;
                }
            }
            catch { /* Malformed bodies are handled by the operation validation. */ }
            return false;
        }

@{
            if (!string.Equals(context.Operation.Id, "mcp-post", System.StringComparison.OrdinalIgnoreCase))
            {
                return "N/A";
            }

            try
            {
                var requestBody = context.Request.Body.As<JObject>(preserveContent: true);
                if (!string.Equals((string)requestBody["method"], "tools/call", System.StringComparison.OrdinalIgnoreCase))
                {
                    return "protocol";
                }

                var toolName = ((string)requestBody.SelectToken("params.name") ?? "unknown").ToLowerInvariant();
                if (toolName == "web" || toolName == "videos" || toolName == "browse" || toolName == "news" || toolName == "images")
                {
                    return toolName;
                }

                return "unknown";
            }
            catch
            {
                return "protocol";
            }
        }

@{
                    try
                    {
                        var body = context.Request.Body.As<JObject>(preserveContent: true);
                        var method = (string)body["method"];
                        if (method == "tools/call")
                        {
                            return (string)body.SelectToken("params.name") == "web"
                                && body.SelectToken("params.arguments") is JObject;
                        }
                        return method == "initialize" || method == "notifications/initialized"
                            || method == "ping" || method == "tools/list"
                    }
                    catch { return false; }
                }

when.set-body:
@{
                    var body = context.Request.Body.As<JObject>();
                    var arguments = context.Operation.Id == "search-web" ? body : (JObject)body["params"]["arguments"];
                    arguments["scopeName"] = "{web-iq-scope-name}";
                    arguments["failOnMissingScope"] = true;
                    return body.ToString(Newtonsoft.Json.Formatting.None);
                }

set-variable.value:
@{
                    try
                    {
                        var raw = context.Response.Body.As<string>(preserveContent: true);
                        if (context.Operation.Id == "search-web")
                        {
                            return (bool?)JObject.Parse(raw)["scopeApplied"] == true;
                        }
                        var messages = new JArray();
                        if (context.Response.Headers.GetValueOrDefault("Content-Type", "").Contains("text/event-stream"))
                        {
                            foreach (var line in raw.Split('\n'))
                            {
                                if (line.StartsWith("data:")) messages.Add(JObject.Parse(line.Substring(5).Trim()));
                            }
                        }
                        else { messages.Add(JObject.Parse(raw)); }
                        var confirmed = false;
                        foreach (var message in messages)
                        {
                            var result = message["result"] as JObject;
                            if (result == null) continue;
                            if ((bool?)result["isError"] == true) return false;
                            var search = result["structuredContent"] as JObject;
                            if (search != null && search["scopeApplied"] != null)
                            {
                                if ((bool?)search["scopeApplied"] != true) return false;
                                confirmed = true;
                            }
                            var content = result["content"] as JArray;
                            if (content == null) continue;
                            foreach (var item in content)
                            {
                                if ((string)item["type"] != "text") continue;
                                JObject textResult;
                                try { textResult = JObject.Parse((string)item["text"]); }
                                catch { continue; }
                                if (textResult["scopeApplied"] == null) continue;
                                if ((bool?)textResult["scopeApplied"] != true) return false;
                                confirmed = true;
                            }
                        }
                        return confirmed;
                    }
                    catch { return false; }
                }
